def transform(grid):
    h, w = len(grid), len(grid[0])
    from collections import Counter
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    out = [row[:] for row in grid]

    for color in set(v for row in grid for v in row if v != bg):
        for dr, dc in ((1, 1), (1, -1)):
            # Each maximal diagonal run is extended at either end, if unobstructed.
            for r in range(h):
                for c in range(w):
                    if grid[r][c] != color:
                        continue
                    pr, pc = r - dr, c - dc
                    if 0 <= pr < h and 0 <= pc < w and grid[pr][pc] == color:
                        continue
                    run = []
                    rr, cc = r, c
                    while 0 <= rr < h and 0 <= cc < w and grid[rr][cc] == color:
                        run.append((rr, cc))
                        rr, cc = rr + dr, cc + dc
                    if len(run) < 2:
                        continue
                    for sr, sc, step_r, step_c in (
                        (run[0][0] - dr, run[0][1] - dc, -dr, -dc),
                        (run[-1][0] + dr, run[-1][1] + dc, dr, dc),
                    ):
                        while 0 <= sr < h and 0 <= sc < w and out[sr][sc] == bg:
                            out[sr][sc] = color
                            sr += step_r
                            sc += step_c
    return out
